import subprocess
from pathlib import Path

runtime = Path("src/do_again/browser/runtime.py")
tests = Path("tests/test_browser_hardening.py")

text = runtime.read_text()
old = '''def _assistant_snapshot(target: cdp.Target) -> dict[str, Any]:
    expression = r"""(() => {""" + _MESSAGE_NODES_JS + r"""
const assistant = messageNodes('assistant');
const latest = assistant.length ? (assistant[assistant.length-1].innerText || assistant[assistant.length-1].textContent || '').trim() : '';
const stop = document.querySelector('[data-testid="stop-button"],button[aria-label="Stop generating"],button[aria-label="Stop response"],button[aria-label="Stop"]');
return {count: assistant.length, latest, busy: !!(stop && !stop.disabled), url: location.href};
})()"""
    value = cdp.evaluate(target, expression, timeout=15.0)
    return value if isinstance(value, dict) else {}
'''
new = '''def _normalize_assistant_text(value: Any) -> str:
    text = str(value or "").strip()
    prefix = "ChatGPT said:"
    if text.startswith(prefix):
        remainder = text[len(prefix):]
        if remainder.startswith("\\n") or remainder.startswith("\\r"):
            return remainder.lstrip("\\r\\n").strip()
    return text


def _assistant_snapshot(target: cdp.Target) -> dict[str, Any]:
    expression = r"""(() => {""" + _MESSAGE_NODES_JS + r"""
const assistant = messageNodes('assistant');
const latest = assistant.length ? (assistant[assistant.length-1].innerText || assistant[assistant.length-1].textContent || '').trim() : '';
const stop = document.querySelector('[data-testid="stop-button"],button[aria-label="Stop generating"],button[aria-label="Stop response"],button[aria-label="Stop"]');
return {count: assistant.length, latest, busy: !!(stop && !stop.disabled), url: location.href};
})()"""
    value = cdp.evaluate(target, expression, timeout=15.0)
    if not isinstance(value, dict):
        return {}
    result = dict(value)
    result["latest"] = _normalize_assistant_text(result.get("latest"))
    return result
'''
if old not in text:
    raise SystemExit("runtime target block not found")
runtime.write_text(text.replace(old, new))

test_text = tests.read_text()
anchor = '''    def test_busy_conversation_keeps_receipt_pending_without_changing_composer(self):
        with patch.object(browser, "_assistant_snapshot", return_value={"busy": True}), patch.object(cdp, "insert_text") as insert:
            with self.assertRaises(browser.BrowserError):
                browser.send_message(self.target, "message")
        insert.assert_not_called()
'''
insert = '''    def test_assistant_snapshot_strips_chatgpt_presentation_prefix(self):
        payload = {
            "count": 1,
            "latest": "ChatGPT said:\\n\\nDO_AGAIN_BROWSER_OK",
            "busy": False,
            "url": self.target.url,
        }
        with patch.object(cdp, "evaluate", return_value=payload):
            snapshot = browser._assistant_snapshot(self.target)
        self.assertEqual(snapshot["latest"], "DO_AGAIN_BROWSER_OK")

    def test_assistant_text_does_not_strip_inline_chatgpt_said_content(self):
        value = "ChatGPT said: this is actual content"
        self.assertEqual(browser._normalize_assistant_text(value), value)

''' + anchor
if anchor not in test_text:
    raise SystemExit("test anchor not found")
tests.write_text(test_text.replace(anchor, insert))

subprocess.run(["python3", "-m", "unittest", "tests.test_browser_hardening"], check=True)
subprocess.run(["python3", "-m", "unittest", "discover", "-s", "tests", "-p", "test_*.py"], check=True)
subprocess.run(["git", "add", str(runtime), str(tests)], check=True)
subprocess.run(["git", "commit", "-m", "Normalize ChatGPT browser response text"], check=True)
subprocess.run(["git", "push", "origin", "main"], check=True)
print(subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip())
